"use strict";

/**
 * The changelog, generated from fragments plus release tags (the D8 ruling on
 * #1555, option C; built in #1561).
 *
 * Source of truth: the operations repo's `scripts/fleet-checks/`; the shared
 * workflow repo's copy is generated by `publish.sh` and never hand-edited.
 *
 * ── THE MODEL ───────────────────────────────────────────────────────────────
 *
 * Each PR adds one file, `changelog.d/<issue>-<slug>.md`:
 *
 *     ---
 *     type: fixed
 *     ships: desktop
 *     ---
 *     The panel reconnects after the machine wakes.
 *
 * Fragments are never assembled into a committed file. Two PRs therefore never
 * edit the same file, and a release adds no commit (#1555, D8).
 *
 * A fragment's release, in each stream it ships in, is the first tag OF THAT
 * STREAM'S PREFIX that contains the commit adding it. The tag-at-deploy ledger
 * already records which commit each release shipped, so the tags are the
 * release history and nothing else needs writing down.
 *
 * The PR number comes from the adding commit's subject, the `(#N)` a squash
 * merge appends, so an author never writes a link that can be wrong.
 *
 * ── STREAMS ─────────────────────────────────────────────────────────────────
 *
 * One tree can ship more than one thing (a site and an installed app). Each is
 * a stream with its own tag prefix; a fragment names the stream(s) it ships in
 * with `ships:`, and the PR check holds that claim to the paths the PR touched,
 * so a PR touching only the app cannot claim to ship in the site (#1561).
 */

const { execFileSync } = require("node:child_process");
const { globToRegExp } = require("./dead-paths.js");

const FRAGMENT_DIR = "changelog.d";
const TYPES = ["added", "changed", "fixed", "removed"];
const TYPE_HEADINGS = { added: "Added", changed: "Changed", fixed: "Fixed", removed: "Removed" };
const FRAGMENT_NAME = /^changelog\.d\/(\d+)-([a-z0-9]+(?:-[a-z0-9]+)*)\.md$/;

/** A file under `changelog.d/` that is not a fragment: its README explains the format. */
const isFragmentPath = (p) => p.startsWith(`${FRAGMENT_DIR}/`) && p.endsWith(".md") && !/\/README\.md$/i.test(p);

// ── fragments ───────────────────────────────────────────────────────────────

/** `web` · `web, desktop` · `[web, desktop]` · `all` · `both` → stream names, or an error string. */
function parseShips(value, streamNames) {
  const list = value.replace(/^\[|\]$/g, "").split(",").map((s) => s.trim()).filter(Boolean);
  if (list.length === 0) return { error: "`ships:` is empty" };
  if (list.length === 1 && list[0] === "all") return { ships: [...streamNames] };
  if (list.length === 1 && list[0] === "both") {
    if (streamNames.length !== 2) return { error: `\`ships: both\` needs exactly two streams; this repo declares ${streamNames.length} — name them` };
    return { ships: [...streamNames] };
  }
  const unknown = list.filter((s) => !streamNames.includes(s));
  if (unknown.length) return { error: `\`ships:\` names ${unknown.map((u) => `"${u}"`).join(", ")}; this repo's streams are ${streamNames.join(", ")}` };
  return { ships: [...new Set(list)] };
}

/**
 * Parse and validate one fragment. Returns every problem at once rather than
 * the first, so one CI round tells an author everything to fix.
 *
 * @returns {{fragment: object|null, errors: string[]}}
 */
function parseFragment(relPath, text, streams) {
  const errors = [];
  const streamNames = Object.keys(streams);
  const name = FRAGMENT_NAME.exec(relPath);
  if (!name) errors.push(`${relPath}: name it changelog.d/<issue>-<slug>.md (digits, then lowercase words joined by "-")`);

  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(text);
  if (!m) {
    errors.push(`${relPath}: starts with a \`---\` frontmatter block holding \`type:\``);
    return { fragment: null, errors };
  }
  const fields = {};
  for (const line of m[1].split(/\r?\n/)) {
    if (!line.trim() || line.trim().startsWith("#")) continue;
    const kv = /^([a-z]+):\s*(.*?)\s*$/.exec(line);
    if (!kv) { errors.push(`${relPath}: cannot read frontmatter line "${line}"`); continue; }
    if (!["type", "ships"].includes(kv[1])) { errors.push(`${relPath}: unknown frontmatter key "${kv[1]}" (type, ships)`); continue; }
    fields[kv[1]] = kv[2].replace(/^["']|["']$/g, "");
  }
  if (!fields.type) errors.push(`${relPath}: \`type:\` is required (${TYPES.join(" | ")})`);
  else if (!TYPES.includes(fields.type)) errors.push(`${relPath}: \`type: ${fields.type}\` is not one of ${TYPES.join(" | ")}`);

  let ships = streamNames.length === 1 ? [streamNames[0]] : null;
  if (fields.ships !== undefined) {
    const r = parseShips(fields.ships, streamNames);
    if (r.error) errors.push(`${relPath}: ${r.error}`);
    else ships = r.ships;
  } else if (streamNames.length > 1) {
    // With two streams, silence would ship the entry nowhere or everywhere;
    // either guess puts a change in release notes it did not ship in.
    errors.push(`${relPath}: \`ships:\` is required here — this repo has streams ${streamNames.join(", ")}`);
  }

  const body = m[2].trim();
  if (!body) errors.push(`${relPath}: the body is one line saying what changed, for a reader of the release notes`);
  else if (/\n/.test(body)) errors.push(`${relPath}: the body is ONE line; this one has ${body.split("\n").length}`);

  if (errors.length) return { fragment: null, errors };
  return {
    fragment: { path: relPath, issue: Number(name[1]), slug: name[2], type: fields.type, ships, body },
    errors,
  };
}

// ── streams and tags ────────────────────────────────────────────────────────

/**
 * Which stream a tag belongs to: the LONGEST prefix it starts with, followed by
 * a digit. The digit rule is what lets `v` and `desktop-v` coexist, and stops
 * a non-release tag such as `bench/x` or `vendor-sync` reading as a release.
 */
function tagStream(tag, streams) {
  let best = null;
  for (const [name, s] of Object.entries(streams)) {
    if (tag.startsWith(s.tagPrefix) && /^\d/.test(tag.slice(s.tagPrefix.length)) &&
        (!best || s.tagPrefix.length > streams[best].tagPrefix.length)) best = name;
  }
  return best;
}

/** Numeric dotted compare after the prefix; a pre-release sorts before its release. */
function compareVersions(a, b) {
  const parse = (v) => {
    const [core, pre] = v.split("-", 2);
    return { nums: core.split(".").map((n) => Number.parseInt(n, 10) || 0), pre: pre ?? null };
  };
  const x = parse(a);
  const y = parse(b);
  for (let i = 0; i < Math.max(x.nums.length, y.nums.length); i++) {
    const d = (x.nums[i] ?? 0) - (y.nums[i] ?? 0);
    if (d) return d;
  }
  if (x.pre === y.pre) return 0;
  if (x.pre === null) return 1;
  if (y.pre === null) return -1;
  return x.pre < y.pre ? -1 : 1;
}

/** The PR a squash commit came from: its trailing `(#N)`, or a merge commit's `#N`. */
function prNumber(subject) {
  const squash = /\(#(\d+)\)\s*$/.exec(subject);
  if (squash) return Number(squash[1]);
  const merge = /^Merge pull request #(\d+)\b/.exec(subject);
  return merge ? Number(merge[1]) : null;
}

const inStream = (p, s) => s.paths.some((g) => globToRegExp(g).test(p)) && !s.excludePaths.some((g) => globToRegExp(g).test(p));

// ── the PR check ────────────────────────────────────────────────────────────

/**
 * A PR changes only docs when every path is under `docs/` or is markdown.
 * This is the fleet's docs-only rule, the one its CI gates skip on (#917), so
 * a PR the code gate skips is the PR this check does not ask a fragment of.
 */
const isDocsOnly = (paths) => paths.length > 0 && paths.every((p) => p.startsWith("docs/") || p.endsWith(".md"));

/** The explicit opt-out: a line `Changelog: none` in the PR body, with the reason after it. */
const OPT_OUT = /^\s*changelog:\s*none\b(.*)$/im;

/**
 * Judge a PR. Pure: the caller reads git and the event.
 *
 * @param {object} o
 * @param {{status:string, path:string}[]} o.changes  `git diff --name-status` rows (A/M/D)
 * @param {Map<string,string>} o.texts  fragment path → content at the PR head
 * @param {object} o.streams
 * @param {string} [o.body]   the PR body
 * @param {string} [o.author] the PR author's login
 * @returns {{errors:string[], notices:string[], fragments:object[]}}
 */
function evaluatePr({ changes, texts, streams, body = "", author = "" }) {
  const errors = [];
  const notices = [];
  const fragments = [];
  const touched = changes.filter((c) => !c.path.startsWith(`${FRAGMENT_DIR}/`)).map((c) => c.path);

  for (const c of changes) {
    if (!isFragmentPath(c.path)) continue;
    if (c.status === "D") {
      // A fragment deleted before its release is a revert; after, it erases the
      // entry from every changelog printed afterwards. Both are allowed, and said.
      notices.push(`${c.path} is deleted — its entry leaves every changelog printed from here on`);
      continue;
    }
    const r = parseFragment(c.path, texts.get(c.path) ?? "", streams);
    errors.push(...r.errors);
    if (!r.fragment) continue;
    const shipErrors = [];
    if (touched.length === 0) {
      notices.push(`${c.path}: this PR changes only fragments, so \`ships:\` has no paths to be checked against`);
    }
    for (const s of touched.length ? r.fragment.ships : []) {
      if (!touched.some((p) => inStream(p, streams[s]))) {
        shipErrors.push(`${c.path}: claims \`ships: ${s}\`, but this PR touches no path that ships in ${s} (${touched.slice(0, 3).join(", ")}${touched.length > 3 ? ", …" : ""})`);
      }
    }
    errors.push(...shipErrors);
    // A fragment with a wrong claim still counts as added: the author wrote
    // one, and "add a fragment" on top of "fix its ships:" would mislead.
    fragments.push({ ...r.fragment, added: c.status === "A", valid: shipErrors.length === 0 });
  }

  const added = fragments.filter((f) => f.added);
  if (added.length === 0) {
    const optOut = OPT_OUT.exec(body);
    if (isDocsOnly(changes.map((c) => c.path))) notices.push("docs-only PR — no fragment needed");
    else if (/\[bot\]$/.test(author)) notices.push(`${author} opened this PR — a bot writes no fragment, and none is asked of it`);
    else if (optOut) notices.push(`opted out in the PR body: "Changelog: none${optOut[1]}"`);
    else {
      errors.push(
        `this PR changes code and adds no fragment. Add ${FRAGMENT_DIR}/<issue>-<slug>.md (type: ${TYPES.join("|")}` +
        `${Object.keys(streams).length > 1 ? `; ships: ${Object.keys(streams).join("|")}` : ""}), ` +
        "or, if no user of this repo can see the change, put a line `Changelog: none — <why>` in the PR body.",
      );
    }
  }
  return { errors, notices, fragments };
}

// ── git ─────────────────────────────────────────────────────────────────────

const git = (root, args, opts = {}) =>
  execFileSync("git", args, { cwd: root, encoding: "utf8", maxBuffer: 256 * 1024 * 1024, ...opts });

const refExists = (root, ref) => {
  try { git(root, ["rev-parse", "--verify", "--quiet", `${ref}^{commit}`], { stdio: ["ignore", "pipe", "ignore"] }); return true; }
  catch { return false; }
};

/** Name-status rows from the merge base of `base` and `head` to `head`, as a PR shows them. */
function prChanges(root, base, head) {
  const out = git(root, ["diff", "--name-status", "--no-renames", `${base}...${head}`]);
  return out.split("\n").filter(Boolean).map((l) => { const [status, p] = l.split("\t"); return { status: status[0], path: p }; });
}

const showAt = (root, ref, p) => git(root, ["show", `${ref}:${p}`]);

function fragmentPathsAt(root, ref) {
  return git(root, ["ls-tree", "-r", "--name-only", ref, "--", FRAGMENT_DIR]).split("\n").filter(isFragmentPath);
}

/**
 * The commit that added each fragment reachable from `ref`, in one log walk.
 * Newest add wins: a fragment deleted and re-added ships with the re-add.
 */
function fragmentAdds(root, ref) {
  const out = git(root, ["log", ref, "--diff-filter=A", "--no-renames", "--format=%x00%H%x09%s", "--name-only", "--", FRAGMENT_DIR]);
  const adds = new Map();
  for (const chunk of out.split("\0").filter(Boolean)) {
    const [head, ...files] = chunk.split("\n").filter(Boolean);
    const [sha, ...rest] = head.split("\t");
    const subject = rest.join("\t");
    for (const f of files) if (!adds.has(f)) adds.set(f, { sha, subject });
  }
  return adds;
}

/** Every release tag, by stream, oldest version first, with its date. */
function streamTags(root, streams) {
  const out = git(root, ["for-each-ref", "--format=%(refname:strip=2)%09%(creatordate:short)", "refs/tags"]);
  const by = Object.fromEntries(Object.keys(streams).map((s) => [s, []]));
  for (const line of out.split("\n").filter(Boolean)) {
    const [tag, date] = line.split("\t");
    const s = tagStream(tag, streams);
    if (s) by[s].push({ tag, date });
  }
  for (const s of Object.keys(by)) by[s].sort((a, b) => compareVersions(a.tag.slice(streams[s].tagPrefix.length), b.tag.slice(streams[s].tagPrefix.length)));
  return by;
}

/**
 * Gather every fragment at `ref` with its PR and, per stream, its release.
 * An invalid fragment is returned in `problems` and left out: the PR check is
 * where it is refused, and a release body is no place to stop a deploy.
 */
function collect(root, { ref = "HEAD", streams }) {
  const adds = fragmentAdds(root, ref);
  const tags = streamTags(root, streams);
  const containing = new Map();
  const firstTag = (sha, stream) => {
    const key = `${sha}:${stream}`;
    if (!containing.has(key)) {
      const prefix = streams[stream].tagPrefix;
      const hits = git(root, ["tag", "--contains", sha, "--list", `${prefix}*`]).split("\n").filter((t) => t && tagStream(t, streams) === stream);
      hits.sort((a, b) => compareVersions(a.slice(prefix.length), b.slice(prefix.length)));
      containing.set(key, hits[0] ?? null);
    }
    return containing.get(key);
  };
  const entries = [];
  const problems = [];
  for (const p of fragmentPathsAt(root, ref)) {
    const { fragment, errors } = parseFragment(p, showAt(root, ref, p), streams);
    if (!fragment) { problems.push(...errors); continue; }
    const add = adds.get(p);
    const releases = {};
    for (const s of fragment.ships) releases[s] = add ? firstTag(add.sha, s) : null;
    entries.push({ ...fragment, sha: add?.sha ?? null, pr: add ? prNumber(add.subject) : null, releases });
  }
  return { entries, tags, problems };
}

// ── rendering ───────────────────────────────────────────────────────────────

const entryLine = (e) => `- ${e.body} (#${e.issue}${e.pr && e.pr !== e.issue ? `, PR #${e.pr}` : ""})`;

/** The type sections of one release, Added → Removed, newest issue first within a type. */
function renderSections(entries) {
  const lines = [];
  for (const t of TYPES) {
    const of = entries.filter((e) => e.type === t).sort((a, b) => b.issue - a.issue || a.slug.localeCompare(b.slug));
    if (!of.length) continue;
    lines.push(`### ${TYPE_HEADINGS[t]}`, "", ...of.map(entryLine), "");
  }
  return lines;
}

/**
 * The body of one release: the entries whose first containing tag in `stream`
 * is `tag`, or, for a tag not yet cut (`pending`), every unreleased entry.
 */
function renderRelease(entries, stream, tag, { pending = false } = {}) {
  const mine = entries.filter((e) => e.ships.includes(stream) && (pending ? e.releases[stream] === null : e.releases[stream] === tag));
  if (!mine.length) return { text: "_No changelog fragments name this release._\n", count: 0 };
  return { text: renderSections(mine).join("\n").replace(/\n+$/, "\n"), count: mine.length };
}

/** The whole changelog of every stream (or one), newest release first. */
function renderChangelog({ entries, tags, streams, only = null, legacy = false }) {
  const names = only ? [only] : Object.keys(streams);
  const multi = Object.keys(streams).length > 1;
  const out = ["# Changelog", "", `Generated from \`${FRAGMENT_DIR}/\` and release tags (D8); never edited by hand.`, ""];
  for (const s of names) {
    const label = multi ? ` — ${s}` : "";
    const unreleased = renderRelease(entries, s, null, { pending: true });
    if (unreleased.count) out.push(`## Unreleased${label}`, "", unreleased.text);
    for (const { tag, date } of [...tags[s]].reverse()) {
      const r = renderRelease(entries, s, tag);
      if (!r.count) continue;
      out.push(`## ${tag}${label} — ${date}`, "", r.text);
    }
  }
  if (legacy) out.push("Releases before the generator: `CHANGELOG.md`, frozen at its last hand-written section.", "");
  return out.join("\n").replace(/\n{3,}/g, "\n\n");
}

module.exports = {
  FRAGMENT_DIR, TYPES, isFragmentPath, parseShips, parseFragment,
  tagStream, compareVersions, prNumber, inStream, isDocsOnly, OPT_OUT, evaluatePr,
  refExists, prChanges, showAt, fragmentPathsAt, fragmentAdds, streamTags, collect,
  entryLine, renderSections, renderRelease, renderChangelog,
};
